package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaPlDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("Allahumma Bika Asbahna", "O Allah, przez Ciebie wchodzimy w poranek i przez Ciebie wchodzimy w wieczór. przez Ciebie żyjemy i przez Ciebie umieramy, i dla Ciebie jest zmartwychwstanie.", "Rano.", "Prorok ﷺ nauczył Towarzyszy odmawiać dziś rano i wieczorem."),
        "dua_allahumma_bika_amsayna" to DuaText("Allahumma Bika Amsayna", "O Allah, przez Ciebie wchodzimy w wieczór i przez Ciebie wchodzimy w poranek. przez Ciebie żyjemy i przez Ciebie umieramy i do Ciebie jest powrót.", "Wieczorem.", "Prorok ﷺ nauczył Towarzyszy odmawiać dziś rano i wieczorem."),
        "dua_afiyah_morning" to DuaText("Prośba o Afiyah", "O Allahu, proszę Cię o przebaczenie i pomyślność na tym świecie i w życiu ostatecznym.", "Prorok ﷺ nigdy nie opuścił tego duetu, ani rano, ani wieczorem.", "Nikt nie otrzymał nic lepszego niż dobre samopoczucie."),
        "dua_afini_fi_badani" to DuaText("Zdrowie ciała, słuchu i wzroku", "O Allahu, obdarz moje ciało dobrostanem. Allahu, obdarz zdrowiem mój słuch. O Allahu, obdarz dobro moim wzrokiem. Nie ma boga oprócz Ciebie.", "Trzy razy każdego ranka i wieczoru.", "Duet dla zdrowia i ochrony zmysłów."),
        "dua_ya_hayyu_aslih" to DuaText("Napraw wszystkie moje sprawy", "O Wiecznie Żyjący, Podtrzymujący, przez Twoje miłosierdzie szukam pomocy: uporządkuj wszystkie moje sprawy i nie zostawiaj mnie samego nawet na mgnienie oka.", "Prorok ﷺ poradził Fatimie (RA), aby mówiła to rano i wieczorem.", "Proś Boga o pomoc w każdej sprawie."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Tasbeeh z Juwayriyah (RA)", "Chwała Allahowi i wszelka chwała należy do Niego – tak wiele, jak Jego stworzenie, tyle, ile Mu się podoba, równe wadze Jego Tronu i atramentowi Jego słów.", "Trzy razy rano – cięższe niż godziny dhikr.", "Trzykrotne wypowiedzenie tych czterech zdań przewyższa dhikr od świtu do południa."),
        "dua_salawat" to DuaText("Durood-e-Ibrahimi", "O Allah, poślij modlitwy za Mahometa ﷺ i rodzinę Mahometa, tak jak wysłałeś modlitwy za Ibrahima (AS) i rodzinę Ibrahima; Jesteś godny pochwały, chwalebny. O Allahu, pobłogosław Muhammada ﷺ i rodzinę Mahometa, tak jak pobłogosławiłeś Ibrahima (AS) i rodzinę Ibrahima; Jesteś godny pochwały, chwalebny.", "Salawat na Proroka ﷺ w modlitwie iw każdym czasie.", "Kto raz pośle salawat, Allah zsyła na niego dziesięć miłosierdzia (Muslim 408)."),
        "dua_wudu_after" to DuaText("Po Wudu", "Świadczę, że nikt nie jest godny czci poza Allahem, Jedynym, który nie ma żadnego współtowarzysza, i że Muhammad ﷺ jest Jego sługą i Wysłannikiem. O Allahu, uczyń mnie wśród tych, którzy pokutują i tych, którzy się oczyszczają.", "Po ukończeniu wudu.", "Osiem bram Raju jest otwartych dla niego, aby mógł wejść, kim chce."),
        "dua_wudu_before" to DuaText("Przed Wudu", "W imię Allaha.", "Kiedy zaczynasz wudu.", "Nie ma (pełnego) wudu dla tego, kto nie wymienia przy tym imienia Allaha."),
        "dua_istiftah" to DuaText("Błaganie otwierające (Sana)", "Chwała Tobie, Allahu, i chwała Tobie. Błogosławione jest Twoje imię, wzniosły jest Twój majestat i nie ma boga oprócz Ciebie.", "Na początku modlitwy, zaraz po otwarciu takbiru.", "Sunna otwierająca duet modlitwy."),
        "dua_ruku" to DuaText("W Ruku", "Chwała mojemu Panu, Wspaniałemu.", "Co najmniej trzy razy w ruku.", "Sunna tasbih ruku."),
        "dua_sujood" to DuaText("W Sujood", "Chwała mojemu Panu, Najwyższemu.", "Co najmniej trzy razy w sujood.", "Sługa jest najbliżej swego Pana, gdy jest w pokłonie (muzułmanin 482)."),
        "dua_rising_ruku" to DuaText("Powstanie z Ruku", "Allah wysłuchuje tego, który Go chwali. Panie nasz, Tobie należy się wszelka chwała.", "Podczas wstawania z ruku i stania w pozycji pionowej.", "Komu „Rabbana wa lakal-hamd” zbiega się z rabbaną aniołów, jego przeszłe grzechy zostają przebaczone."),
        "dua_between_sajdas" to DuaText("Między dwoma Sajdami", "Mój Panie, przebacz mi. Mój Panie, przebacz mi.", "Siedząc pomiędzy dwoma pokłonami.", "Sunna dua siedzenia pomiędzy pokłonami."),
        "dua_before_salam_four" to DuaText("Schronienie przed czterema rzeczami (przed Salam)", "O Allahu, szukam schronienia u Ciebie przed karą piekielną, karą grobową, próbami życia i śmierci oraz przed złem procesu Fałszywego Mesjasza (Dajjal).", "Po ostatnim tashahhud i salawat, przed salam.", "Prorok ﷺ nakazał szukać schronienia przed tymi czterema rzeczami."),
        "dua_qunoot_witr" to DuaText("Qunoot w Witr", "O Allahu, prowadź mnie wśród tych, którymi prowadziłeś, obdarz mnie pomyślnością wśród tych, których obdarzyłeś dobrobytem, ​​weź mnie pod swoją opiekę wśród tych, których wziąłeś pod swoją opiekę, pobłogosław mnie w tym, co dałeś i chroń mnie przed złem tego, co postanowiłeś. Ty wydajesz wyroki, a nikt nie wydaje wyroków przeciwko Tobie, a ten, z którym się przyjaźnisz, nigdy nie doznaje upokorzenia. Błogosławiony i Wywyższony jesteś Ty, nasz Panie.", "W modlitwie Witr – Prorok ﷺ nauczył go Hasana ibn Alego (RA).", "Sunna qunoot witr. (Wśród Hanafich dobrze znane jest również „Allahumma inna nasta'inuka”)."),
        "dua_qunoot_hanafi" to DuaText("Qunoot (Allahumma Inna Nasta'inuka)", "O Allahu, szukamy Twojej pomocy i przebaczenia, wierzymy w Ciebie i na Tobie polegamy, wychwalamy Cię w najlepszy sposób, dziękujemy Ci i nie jesteśmy niewdzięczni, i porzucamy każdego, kto jest Tobie nieposłuszny. O Allah, tylko Ciebie czcimy, do Ciebie modlimy się i kłaniamy się, do Ciebie śpieszymy i dążymy, mamy nadzieję na Twoje miłosierdzie i boimy się Twojej kary; z pewnością Twoja kara dosięgnie niewiernych.", "In witr — praktyka Hanafich.", "Zgłoszono od Umara (RA) w qunoot."),
        "dua_sleep_aslamtu" to DuaText("Ostatnie słowa przed snem", "O Allahu, poddaję się Tobie, powierzam Ci moją sprawę i oddaję swoje plecy Twojej opiece, z nadziei w Tobie i strachu przed Tobą. Nie ma schronienia ani ucieczki przed Tobą, jak tylko do Ciebie. Wierzę w Twoją Księgę, którą objawiłeś, i w Twojego Proroka, którego posłałeś.", "Po wudu, leżenie na prawym boku — ostatnie słowa przed snem.", "Jeśli umrze tej nocy, umrze w fitrah (islamie)."),
        "dua_waking_night" to DuaText("Budzenie się w nocy", "Nikt nie jest godny czci poza Allahem, Jedynym, który nie ma żadnego współtowarzysza. Do Niego należy panowanie i do Niego należy chwała. On jest nad każdą rzeczą wszechwładny. Wszelka chwała jest Allahowi, chwała Allahowi, nikt nie ma prawa być czczonym poza Allahem. Allah jest Największy i nie ma siły ani mocy inaczej niż dzięki Allahowi. O Allahu, przebacz mi.", "Po przebudzeniu w nocy.", "Jego dua zostaje wysłuchane i jeśli odmawia wudu i modli się, jego modlitwa zostaje przyjęta."),
        "dua_hamm_ibn_masud" to DuaText("Dua na smutek (Ibn Mas'ud)", "O Allahu, jestem Twoim sługą, synem Twojego sługi, synem Twojej służebnicy. Moja grzywa jest w Twoich rękach, Twój rozkaz nade mną jest wykonywany, a Twój wyrok dotyczący mnie jest sprawiedliwy. Proszę Cię o każde imię, które jest Twoje, którym nadałeś sobie imię, którym objawiłeś w Swojej Księdze, lub którego nauczałeś jakiekolwiek stworzenie, lub które przechowujesz w wiedzy tego, co skryte, abyś uczynił Koran źródłem mojego serca, światłem mojej piersi, usuwającym mój smutek i znikającym zmartwienia.", "W smutku i utrapieniu – Allah zastępuje smutek radością.", "Allah usuwa jego zmartwienia i smutek, a zamiast tego obdarza go radością."),
        "dua_difficulty_sahl" to DuaText("Kiedy coś jest trudne", "O Allahu, nic nie jest łatwe oprócz tego, co Ty uczynisz łatwym, a Ty sprawiasz, że trudne staje się łatwym, jeśli chcesz.", "Kiedy coś wydaje się trudne.", "Łatwość w egzaminach i trudnych zadaniach."),
        "dua_musibah" to DuaText("Po nieszczęściu (Istirja)", "Należymy do Allaha i do Niego powrócimy. O Allahu, nagrodź mnie w moim nieszczęściu i zastąp mnie czymś lepszym.", "W przypadku jakiejkolwiek straty lub nieszczęścia.", "Allah z pewnością daje coś lepszego — Umm Salamah (RA) otrzymała Proroka ﷺ."),
        "dua_debt" to DuaText("O uwolnienie od długów", "O Allahu, wystarczy mi tego, co uznałeś za dozwolone, w porównaniu z tym, co uznałeś za nielegalne, i dzięki swojej szczodrości uniezależnij mnie od wszystkich poza Tobą.", "O spłatę długów — nauczał Ali (RA).", "Nawet jeśli dług będzie jak góra, Allah go ureguluje."),
        "dua_anger" to DuaText("Kiedy zły", "Szukam schronienia u Allaha przed Szaytanem, przeklętym.", "Kiedy zły.", "Prorok ﷺ powiedział: jeśli to powie, jego gniew zniknie."),
        "dua_waswasa" to DuaText("Przeciwko Waswasie w wierze", "Wierzę w Allaha i Jego Posłańców.", "Kiedy nadchodzą szatańskie szepty o wierze.", "Kiedy nadejdzie szept, powiedz to i zatrzymaj się (i także szukaj schronienia u Allaha)."),
        "dua_travel_full" to DuaText("Kompletna prośba podróżna", "O Allahu, prosimy Cię w tej podróży o prawość i pobożność oraz o uczynki, które Ci się podobają. O Allahu, uczyń tę podróż łatwą dla nas i skróć jej dystans. O Allahu, jesteś towarzyszem podróży i opiekunem rodziny.", "Wyruszając w podróż, po „Subhanalladhi sakhkhara”.", "Kompletny duet podróżniczy Sunnah."),
        "dua_return_travel" to DuaText("Powrót z podróży", "Wracamy, pokutując, wielbiąc i wychwalając naszego Pana.", "Po powrocie z podróży.", "Prorok ﷺ powiedział to po powrocie z podróży."),
        "dua_farewell_traveller" to DuaText("Pożegnanie podróżnika", "Powierzam Allahowi waszą religię, wasze zaufanie i wynik waszych czynów.", "Żegnając podróżnika.", "To, co zostało powierzone Allahowi, nigdy nie jest stracone."),
        "dua_entering_town" to DuaText("Zatrzymanie się w danym miejscu", "Szukam schronienia w doskonałych słowach Allaha przed złem wszystkiego, co stworzył.", "Podczas zatrzymania się w danym miejscu lub przybycia do nowego miasta.", "Nic mu nie zaszkodzi, dopóki stamtąd nie odejdzie."),
        "dua_boarding_ship" to DuaText("Wejście na statek/pojazd", "W imię Allaha żegluje i kotwiczy. Zaprawdę, mój Pan jest Przebaczający, Litościwy.", "Podczas wchodzenia na pokład statku lub pojazdu – słowa Proroka Nuha (AS).", "Werset Koranu — dua arki Nuha (AS)."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Istighfar z Hayyulem-Qayyumem", "Szukam przebaczenia u Allaha, poza którym nie ma boga, Wiecznie Żyjącego, Podtrzymującego, i zwracam się do Niego w pokucie.", "O pokutę.", "Jego grzechy zostały przebaczone, nawet jeśli uciekł z pola bitwy."),
        "dua_rabbighfir_warham" to DuaText("Rabinghfir Warham", "Panie mój, przebacz i zmiłuj się, bo Ty jesteś najlepszy z tych, którzy okazują miłosierdzie.", "Koraniczny duet – o przebaczenie i miłosierdzie.", "Ostatni werset Sury al-Mu'minun."),
        "dua_majlis_kaffarah" to DuaText("Kaffarat al-Madżlis", "Chwała Tobie, Allahu, i chwała Tobie. Świadczę, że nie ma boga oprócz Ciebie. Szukam Twojego przebaczenia i zwracam się do Ciebie w pokucie.", "Kiedy wstajesz ze spotkania.", "Staje się odpokutowaniem za wszelkie zło, które zostało powiedziane na zgromadzeniu."),
        "dua_jami_forgiveness" to DuaText("Kompleksowe przebaczenie", "O Allahu, przebacz mi moje błędy, moją niewiedzę, moje nadmiary w moich sprawach i wszystko, co wiesz lepiej ode mnie.", "Obszerny duet Proroka ﷺ.", "Prorok ﷺ zwykł tworzyć ten duet."),
        "dua_parents_nuh" to DuaText("Dua of Nuh (AS) dla rodziców", "Panie mój, przebacz mi, moim rodzicom, każdemu, kto wchodzi do mojego domu jako wierzący, i wszystkim wierzącym mężczyznom i wierzącym kobietom.", "Za rodziców i wierzących.", "Dua Proroka Nuha (AS)."),
        "dua_shukr_parents" to DuaText("Wdzięczność dla rodziców i prawego potomstwa", "Panie mój, pozwól mi być wdzięcznym za Twoją łaskę, którą obdarzyłeś mnie i moich rodziców, i czynić dobre uczynki, które podobają się Tobie, i uczynić moje potomstwo sprawiedliwym. Zwracam się do Ciebie w pokucie i jestem wśród tych, którzy się poddają.", "Koraniczny dua osiągnięcia wieku czterdziestu lat.", "Wdzięczność, dobre uczynki i prawość swoich dzieci – wszystko w jednym duecie."),
        "dua_intimacy" to DuaText("Przed stosunkiem małżeńskim", "W imię Allaha. O Allahu, trzymaj Szaytana z dala od nas i trzymaj Szaytana z dala od tego, co nam (dzieciom) dajesz.", "Przed relacjami małżeńskimi.", "Jeśli zostanie wydane dziecko, Szaytan nigdy go nie skrzywdzi."),
        "dua_ibrahim_children_protection" to DuaText("Ochrona Domu i Dzieci", "Panie mój, zabezpiecz to miasto i chroń mnie i moje dzieci od oddawania czci bożkom.", "Dua proroka Ibrahima (AS) — w intencji bezpieczeństwa miasta i jego dzieci.", "Dua za niezachwiane przestrzeganie tawhid."),
        "dua_drinking_milk" to DuaText("Kiedy pije mleko", "O Allahu, pobłogosław to dla nas i daj nam go więcej.", "Podczas picia mleka.", "Mleko wystarczy jako pokarm i napój."),
        "dua_iftar_host" to DuaText("Kiedy zrywasz post z innymi", "Niech poszczący przerywają post z Tobą, niech sprawiedliwi spożywają Twój pokarm, a aniołowie modlą się za Tobą.", "Kiedy przerywasz post w czyimś domu.", "Dua Proroka ﷺ dla gospodarza."),
    )
}
